}
RESOURCES = ("fiber", "nectar", "spores", "compost", "mulch", "tonic")
STRUCTURES = ("none", "shade_cloth", "rain_barrel", "bee_house", "log")
LAYERS = ("art", "moisture", "nutrients", "shade", "vitality", "mulch", "stress", "terrain")


def field_guide():
